import{_ as e,c as l,o as i,ah as t}from"./chunks/framework.CRFddiXd.js";const q=JSON.parse('{"title":"Сборки модов","description":"Сборки модов в Stuzhik — версионно-независимые наборы модов, которые можно применить к любому экземпляру одной кнопкой.","frontmatter":{"description":"Сборки модов в Stuzhik — версионно-независимые наборы модов, которые можно применить к любому экземпляру одной кнопкой.","head":[["meta",{"name":"keywords","content":"stuzhik сборки модов, стужик, mod collections, наборы модов minecraft, применить моды к экземпляру"}]]},"headers":[],"relativePath":"guide/collections.md","filePath":"guide/collections.md"}'),o={name:"guide/collections.md"};function r(h,a,n,d,u,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="сборки-модов" tabindex="-1">Сборки модов <a class="header-anchor" href="#сборки-модов" aria-label="Permalink to &quot;Сборки модов&quot;">​</a></h1><p>Набор модов без привязки к конкретной версии Minecraft или загрузчику. Собираешь один раз — применяешь к любому экземпляру, а Stuzhik сам подбирает подходящие версии модов под него.</p><p>Это не модпак: сборка не содержит конфигов и настроек — только список модов, которые ты обычно ставишь вместе.</p><h2 id="зачем-это-нужно" tabindex="-1">Зачем это нужно <a class="header-anchor" href="#зачем-это-нужно" aria-label="Permalink to &quot;Зачем это нужно&quot;">​</a></h2><p>Модпак фиксирует версии. Сборка — нет. Если у тебя есть привычный набор твоих любимых модов (например, оптимизация + QoL), и ты постоянно создаёшь новые экземпляры под разные версии MC — вместо ручной переустановки одного и того же набора применяешь сборку, и подходящие версии подбираются автоматически под конкретный экземпляр.</p><h2 id="создание-сборки" tabindex="-1">Создание сборки <a class="header-anchor" href="#создание-сборки" aria-label="Permalink to &quot;Создание сборки&quot;">​</a></h2><h3 id="с-нуля" tabindex="-1">С нуля <a class="header-anchor" href="#с-нуля" aria-label="Permalink to &quot;С нуля&quot;">​</a></h3><ol><li>Раздел &quot;Сборки модов&quot; в сайдбаре → &quot;Создать&quot;</li><li>Название и (опционально) описание</li><li>Добавляй моды через встроенный каталог — поиск, фильтры, всё как в обычном браузере модов</li></ol><h3 id="из-установленного-экземпляра" tabindex="-1">Из установленного экземпляра <a class="header-anchor" href="#из-установленного-экземпляра" aria-label="Permalink to &quot;Из установленного экземпляра&quot;">​</a></h3><ol><li>Экземпляр → вкладка &quot;Моды&quot; → &quot;В сборку&quot;</li><li>Выбери, какие моды включить (можно не все)</li><li>Сохрани как новую сборку или добавь в существующую</li></ol><h2 id="применение-сборки" tabindex="-1">Применение сборки <a class="header-anchor" href="#применение-сборки" aria-label="Permalink to &quot;Применение сборки&quot;">​</a></h2><h3 id="к-существующему-экземпляру" tabindex="-1">К существующему экземпляру <a class="header-anchor" href="#к-существующему-экземпляру" aria-label="Permalink to &quot;К существующему экземпляру&quot;">​</a></h3><ol><li>Экземпляр → вкладка &quot;Моды&quot; → &quot;Применить сборку&quot;</li><li>Выбери сборку</li><li>Stuzhik покажет предпросмотр: что установится, что пропустится (уже есть или несовместимо), что не удалось найти под эту версию/загрузчик</li><li>Подтверди</li></ol><h3 id="при-создании-нового-экземпляра" tabindex="-1">При создании нового экземпляра <a class="header-anchor" href="#при-создании-нового-экземпляра" aria-label="Permalink to &quot;При создании нового экземпляра&quot;">​</a></h3><p>В форме создания экземпляра есть отдельный шаг выбора сборки — моды установятся сразу вместе с самим экземпляром.</p><h2 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h2><ul><li><strong>В модпак</strong> — сборку можно экспортировать в <code>.mrpack</code> (Modrinth) или <code>.stzhk</code> (формат Stuzhik), зафиксировав версии под конкретную MC-версию</li><li><strong>Импорт модпака в сборку</strong> — можно и наоборот: взять существующий модпак (Modrinth или CurseForge) и сохранить его список модов как версионно-независимую сборку</li></ul><h2 id="управление" tabindex="-1">Управление <a class="header-anchor" href="#управление" aria-label="Permalink to &quot;Управление&quot;">​</a></h2><ul><li>Дубликат сборки — если хочешь сделать вариацию не трогая оригинал</li><li>Переименование, своя иконка</li><li>Drag &amp; drop для переупорядочивания модов внутри сборки</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше? <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше?&quot;">​</a></h2><ul><li><a href="/guide/mods.html">Управление модами</a></li><li><a href="/guide/modpacks.html">Модпаки</a></li><li><a href="/faq.html">FAQ</a></li></ul>',21)])])}const m=e(o,[["render",r]]);export{q as __pageData,m as default};
